          store.append(UInt8(ascii: "%"))
          store.append(UInt8(ascii: "%"))
        } else {
          store.append(UInt8(truncatingIfNeeded: value))
        }
      default:
        // not an escape: the backslash is dropped
        store.append(e)
      }
      i += 1
    }
    fmt = store
    return false
